# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA İMAN ESASLARI (ÂMENTÜ PRENSİPLERİ — 6 ESAS)</text>\n  <rect x="20" y="45" width="210" height="90" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. ALLAH\'A İMAN (TEVHİD)</text>\n  <text x="125" y="86" text-anchor="middle" font-size="10.5" fill="#1e3a8a">Varlığı zorunlu (Vâcibü\'l-Vücûd),</text>\n  <text x="125" y="102" text-anchor="middle" font-size="10.5" fill="#1e3a8a">eşi ve benzeri olmayan Yaratıcı</text>\n  <text x="125" y="118" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">(İhlâs, 1-4; Bakara, 255)</text>\n  <rect x="245" y="45" width="210" height="90" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. MELEKLERE İMAN</text>\n  <text x="350" y="86" text-anchor="middle" font-size="10.5" fill="#14532d">Nurdan yaratılan, günah işlemeyen</text>\n  <text x="350" y="102" text-anchor="middle" font-size="10.5" fill="#14532d">gaybî varlıklar (Cebrail, Mikâil,</text>\n  <text x="350" y="118" text-anchor="middle" font-size="10.5" fill="#14532d">İsrafil, Azrail, Kirâmen Kâtibîn)</text>\n  <rect x="470" y="45" width="210" height="90" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">3. KİTAPLARA İMAN</text>\n  <text x="575" y="86" text-anchor="middle" font-size="10.5" fill="#713f12">Suhuflar ve Dört Büyük İlahi Vahiy:</text>\n  <text x="575" y="102" text-anchor="middle" font-size="10.5" fill="#713f12">Tevrat, Zebur, İncil ve son vahiy</text>\n  <text x="575" y="118" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Kur\'an-ı Kerim (Hicr, 9)</text>\n  <rect x="20" y="150" width="210" height="90" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="125" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">4. PEYGAMBERLERE İMAN</text>\n  <text x="125" y="191" text-anchor="middle" font-size="10.5" fill="#581c87">Sıdk, Emanet, Tebliğ, Fetanet, İsmet</text>\n  <text x="125" y="207" text-anchor="middle" font-size="10.5" fill="#581c87">Hz. Âdem\'den Hâtemü\'l-Enbiyâ</text>\n  <text x="125" y="223" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">Hz. Muhammed\'e (sav) (Ahzâb, 40)</text>\n  <rect x="245" y="150" width="210" height="90" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="350" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">5. AHİRETE İMAN</text>\n  <text x="350" y="191" text-anchor="middle" font-size="10.5" fill="#7c2d12">Kıyamet, Ba\'s, Haşir, Mahşer,</text>\n  <text x="350" y="207" text-anchor="middle" font-size="10.5" fill="#7c2d12">Hesap, Mizan, Cennet ve Cehennem</text>\n  <text x="350" y="223" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9a3412">Sorumluluk ve İlahi Adalet</text>\n  <rect x="470" y="150" width="210" height="90" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="2"/>\n  <text x="575" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">6. KAZA VE KADERE İMAN</text>\n  <text x="575" y="191" text-anchor="middle" font-size="10.5" fill="#831843">Kader: İlahi ölçü, plan ve takdir</text>\n  <text x="575" y="207" text-anchor="middle" font-size="10.5" fill="#831843">Kaza: Takdir edilenin gerçekleşmesi</text>\n  <text x="575" y="223" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9d174d">Cüz\'î İrade, Sorumluluk ve Tevekkül</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ALLAH\'IN SIFATLARI (ZATİ VE SUBUTİ SIFATLAR)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ZATİ SIFATLAR (SADECE ALLAH\'A ÖZGÜ)</text>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• Vücud: Var olması (varlığı zorunludur, yokluğu düşünülemez).</text>\n  <text x="42" y="118" font-size="11" font-weight="bold" fill="#1e3a8a">• Kıdem: Ezeli olması, varlığının başlangıcı olmaması.</text>\n  <text x="42" y="142" font-size="11" font-weight="bold" fill="#1e3a8a">• Beka: Ebedî olması, varlığının sonu olmaması.</text>\n  <text x="42" y="166" font-size="11" font-weight="bold" fill="#1e3a8a">• Vahdaniyet: Zatında, sıfatlarında ve fiillerinde bir olması.</text>\n  <text x="42" y="190" font-size="11" font-weight="bold" fill="#1e3a8a">• Muhalefetün li\'l-havâdis: Yaratılmışlara benzememesi.</text>\n  <text x="42" y="214" font-size="11" font-weight="bold" fill="#1e3a8a">• Kıyam bi-nefsihî: Var olmak için hiçbir şeye muhtaç olmaması.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">SUBUTİ SIFATLAR (MUTLAK KEMAL SIFATLARI)</text>\n  <text x="377" y="92" font-size="11" font-weight="bold" fill="#14532d">• Hayat: Diri ve canlı olması, hayatın kaynağı olması.</text>\n  <text x="377" y="113" font-size="11" font-weight="bold" fill="#14532d">• İlim: Gizli ve açık, geçmiş ve gelecek her şeyi bilmesi.</text>\n  <text x="377" y="134" font-size="11" font-weight="bold" fill="#14532d">• Semi: Her şeyi işitmesi (duymak için araca muhtaç değil).</text>\n  <text x="377" y="155" font-size="11" font-weight="bold" fill="#14532d">• Basar: Her şeyi görmesi (karanlıkta ve gizlide olanı görür).</text>\n  <text x="377" y="176" font-size="11" font-weight="bold" fill="#14532d">• İrade: Dilemesi, bir şeyin öyle olmasını tercih etmesi.</text>\n  <text x="377" y="197" font-size="11" font-weight="bold" fill="#14532d">• Kudret: Her şeye gücünün yetmesi (sınırsız güç sahibi).</text>\n  <text x="377" y="218" font-size="11" font-weight="bold" fill="#14532d">• Kelam ve Tekvin: Konuşması (vahiy) ve yoktan yaratması.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AYET VE HADİSLER BAĞLAMINDA İMAN ESASLARININ SINIFLANDIRILMASI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">USÛL-İ SELÂSE (ÜÇ TEMEL İNANÇ ESASI)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#713f12">1. Tevhid (Ulûhiyet — Allah\'a İman):</text>\n  <text x="52" y="114" font-size="10.5" fill="#713f12">İnanç sisteminin merkezidir; kader ve kaza</text>\n  <text x="52" y="128" font-size="10.5" fill="#713f12">Allah\'ın ilim, irade ve kudret sıfatlarıyla ilgilidir.</text>\n  <text x="42" y="152" font-size="11.5" font-weight="bold" fill="#713f12">2. Nübüvvet (Peygamberlik):</text>\n  <text x="52" y="170" font-size="10.5" fill="#713f12">Meleklere ve ilahi vahiylere iman bu başlıkla</text>\n  <text x="52" y="184" font-size="10.5" fill="#713f12">bütünleşir (vahyi getiren Cebrail ve peygamberler).</text>\n  <text x="42" y="208" font-size="11.5" font-weight="bold" fill="#713f12">3. Ahiret (Meâd): Öldükten sonra diriliş ve hesap.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">TEMEL DELİLLER: AYETLER VE CİBRİL HADİSİ</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#581c87">• Bakara Suresi, 285. Ayet (Âmenerrasûlü):</text>\n  <text x="385" y="113" font-size="10.5" fill="#4c1d95">"Peygamber ve müminler; Allah\'a, meleklerine,</text>\n  <text x="385" y="128" font-size="10.5" fill="#4c1d95">ilahi vahiylerine ve peygamberlerine iman etti..."</text>\n  <text x="377" y="152" font-size="11" font-weight="bold" fill="#581c87">• Nisâ Suresi, 136. Ayet ve Kamer Suresi, 49. Ayet:</text>\n  <text x="385" y="169" font-size="10.5" fill="#4c1d95">"Biz her şeyi bir ölçüye (kadere) göre yarattık."</text>\n  <text x="377" y="193" font-size="11" font-weight="bold" fill="#581c87">• Cibril Hadisi (Müslim, Îmân, 1):</text>\n  <text x="385" y="210" font-size="10.5" fill="#4c1d95">"İman; Allah\'a, meleklerine, kitaplarına, elçilerine,</text>\n  <text x="385" y="225" font-size="10.5" fill="#4c1d95">ahiret gününe, kadere (hayır ve şerre) inanmandır."</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
